steps_json:
[
    {
        "title": "看清数量关系",
        "description": "袋子里共有两种球，总数是 $50$ 个，已知红球个数比黄球的 $3$ 倍多 $2$ 个。",
        "bubbleText": "这类题先别急着求概率，先把红球和黄球各有多少个找出来。",
        "bubblePos": {
            "x": 245,
            "y": 150
        }
    },
    {
        "title": "设黄球为未知数",
        "description": "设黄球有 $y$ 个，那么红球有 $3y+2$ 个。",
        "bubbleText": "因为题目说“红球比黄球的3倍多2个”，所以红球就能写成 $3y+2$。",
        "bubblePos": {
            "x": 510,
            "y": 95
        }
    },
    {
        "title": "列出总数方程",
        "description": "根据“红球和黄球共 $50$ 个”，列方程：$y+(3y+2)=50$。",
        "bubbleText": "黄球数加红球数，就是总数 50，这一步是关键的等量关系。",
        "bubblePos": {
            "x": 555,
            "y": 245
        }
    },
    {
        "title": "化简方程",
        "description": "合并同类项：$y+3y+2=50$，所以 $4y+2=50$，再得 $4y=48$。",
        "bubbleText": "把4个 $y$ 合在一起，再把右边整理一下，就离答案更近了。",
        "bubblePos": {
            "x": 560,
            "y": 365
        }
    },
    {
        "title": "求出黄球个数",
        "description": "两边同时除以 $4$，得到 $y=12$，所以黄球有 $12$ 个。",
        "bubbleText": "未知数 $y$ 求出来了，说明黄球一共有 12 个。",
        "bubblePos": {
            "x": 505,
            "y": 480
        }
    },
    {
        "title": "求出红球个数",
        "description": "红球个数为 $3\\times 12+2=36+2=38$，所以红球有 $38$ 个。",
        "bubbleText": "把黄球数 12 代回去，就能算出红球是 38 个。",
        "bubblePos": {
            "x": 170,
            "y": 470
        }
    },
    {
        "title": "写出概率公式",
        "description": "摸到黄球的概率是黄球个数除以总个数，即 $\\frac{12}{50}$。",
        "bubbleText": "随机摸一个球，每个球机会一样，所以“想要的球数 ÷ 全部球数”。",
        "bubblePos": {
            "x": 540,
            "y": 230
        }
    },
    {
        "title": "约分得结果",
        "description": "将 $\\frac{12}{50}$ 约分，分子分母同时除以 $2$，得 $\\frac{6}{25}$。",
        "bubbleText": "最后把分数化成最简分数，更规范也更容易看清答案。",
        "bubblePos": {
            "x": 590,
            "y": 485
        }
    },
    {
        "title": "验算并确认",
        "description": "验算：$12+38=50$，并且 $38=3\\times 12+2$，都符合题意，所以摸到黄球的概率是 $\\frac{6}{25}$。",
        "bubbleText": "回头检查总数和倍数关系都对，说明我们的答案是正确的：$\\frac{6}{25}$。",
        "bubblePos": {
            "x": 500,
            "y": 70
        }
    }
]
